+package main
+
+import (
+	"fmt"
+	"os"
+)
+
+// Simulating the BitSet structure and relevant functions
+type BitSet struct {
+	length uint
+	set    []uint64
+}
+
+const wordSize = 64
+const wordMask = wordSize - 1
+const log2WordSize = 6
+
+func Cap() uint {
+	return ^uint(0)
+}
+
+func wordsNeeded(i uint) int {
+	if i > (Cap() - wordMask) {
+		return int(Cap() >> log2WordSize)
+	}
+	return int((i + wordMask) >> log2WordSize)
+}
+
+func (b *BitSet) extendSet(i uint) {
+	if i >= Cap() {
+		panic("You are exceeding the capacity")
+	}
+	nsize := wordsNeeded(i + 1)
+	if b.set == nil {
+		b.set = make([]uint64, nsize)
+	} else if cap(b.set) >= nsize {
+		b.set = b.set[:nsize] // fast resize
+	} else if len(b.set) < nsize {
+		newset := make([]uint64, nsize, 2*nsize) // increase capacity 2x
+		copy(newset, b.set)
+		b.set = newset
+	}
+	// Fixed: Only update length if i is >= current length
+	if i >= b.length {
+		b.length = i + 1
+	}
+}
+
+func (b *BitSet) Set(i uint) *BitSet {
+	if i >= b.length { // if we need more bits, make 'em
+		b.extendSet(i)
+	}
+	// Simplified setting logic for testing
+	return b
+}
+
+func main() {
+	// Test case: Create a BitSet, set a high bit, then set a lower bit
+	// and check that the length is preserved correctly
+	b := &BitSet{}
+	
+	// Set bit at position 100, this should set length to 101
+	b.Set(100)
+	fmt.Printf("After setting bit 100, length = %d\n", b.length)
+	
+	// Set bit at position 50, this should NOT change the length
+	b.Set(50)
+	fmt.Printf("After setting bit 50, length = %d\n", b.length)
+	
+	// Expected: length should still be 101, not 51
+	if b.length == 101 {
+		fmt.Println("TEST PASSED: Length correctly preserved")
+		os.Exit(0)
+	} else {
+		fmt.Printf("TEST FAILED: Expected length 101, got %d\n", b.length)
+		os.Exit(1)
+	}
+}

